-- G2.5 explicit Snowflake-supported Gold tag and minimization validation.
USE DATABASE TRUSTED_AI_GOVERNANCE;

WITH T AS (
 SELECT 'PAYMENT_EXCEPTION_INVESTIGATION' PRODUCT,'PAYMENT_EXCEPTION' DOMAIN,'OPERATIONAL_SENSITIVE' CLASSIFICATION,'HIGH' SENSITIVITY,
 SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.DATA_LAYER','TRUSTED_AI_GOVERNANCE.GOLD.PAYMENT_EXCEPTION_INVESTIGATION','TABLE') LAYER,
 SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.SYNTHETIC_DATA','TRUSTED_AI_GOVERNANCE.GOLD.PAYMENT_EXCEPTION_INVESTIGATION','TABLE') SYNTHETIC,
 SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.DATA_DOMAIN','TRUSTED_AI_GOVERNANCE.GOLD.PAYMENT_EXCEPTION_INVESTIGATION','TABLE') ACTUAL_DOMAIN,
 SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.OWNER_DOMAIN','TRUSTED_AI_GOVERNANCE.GOLD.PAYMENT_EXCEPTION_INVESTIGATION','TABLE') OWNER,
 SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.PERMITTED_PURPOSE','TRUSTED_AI_GOVERNANCE.GOLD.PAYMENT_EXCEPTION_INVESTIGATION','TABLE') PURPOSE,
 SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.DATA_CLASSIFICATION','TRUSTED_AI_GOVERNANCE.GOLD.PAYMENT_EXCEPTION_INVESTIGATION','TABLE') ACTUAL_CLASSIFICATION,
 SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.SENSITIVITY_LEVEL','TRUSTED_AI_GOVERNANCE.GOLD.PAYMENT_EXCEPTION_INVESTIGATION','TABLE') ACTUAL_SENSITIVITY
 UNION ALL SELECT 'PAYMENT_EXCEPTION_DAILY_METRICS','PAYMENT_EXCEPTION','GOVERNED_BUSINESS_INFORMATION','MODERATE',SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.DATA_LAYER','TRUSTED_AI_GOVERNANCE.GOLD.PAYMENT_EXCEPTION_DAILY_METRICS','TABLE'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.SYNTHETIC_DATA','TRUSTED_AI_GOVERNANCE.GOLD.PAYMENT_EXCEPTION_DAILY_METRICS','TABLE'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.DATA_DOMAIN','TRUSTED_AI_GOVERNANCE.GOLD.PAYMENT_EXCEPTION_DAILY_METRICS','TABLE'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.OWNER_DOMAIN','TRUSTED_AI_GOVERNANCE.GOLD.PAYMENT_EXCEPTION_DAILY_METRICS','TABLE'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.PERMITTED_PURPOSE','TRUSTED_AI_GOVERNANCE.GOLD.PAYMENT_EXCEPTION_DAILY_METRICS','TABLE'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.DATA_CLASSIFICATION','TRUSTED_AI_GOVERNANCE.GOLD.PAYMENT_EXCEPTION_DAILY_METRICS','TABLE'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.SENSITIVITY_LEVEL','TRUSTED_AI_GOVERNANCE.GOLD.PAYMENT_EXCEPTION_DAILY_METRICS','TABLE')
 UNION ALL SELECT 'PAYMENT_EXCEPTION_PERIOD_COMPARISON','PAYMENT_EXCEPTION','GOVERNED_BUSINESS_INFORMATION','MODERATE',SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.DATA_LAYER','TRUSTED_AI_GOVERNANCE.GOLD.PAYMENT_EXCEPTION_PERIOD_COMPARISON','TABLE'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.SYNTHETIC_DATA','TRUSTED_AI_GOVERNANCE.GOLD.PAYMENT_EXCEPTION_PERIOD_COMPARISON','TABLE'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.DATA_DOMAIN','TRUSTED_AI_GOVERNANCE.GOLD.PAYMENT_EXCEPTION_PERIOD_COMPARISON','TABLE'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.OWNER_DOMAIN','TRUSTED_AI_GOVERNANCE.GOLD.PAYMENT_EXCEPTION_PERIOD_COMPARISON','TABLE'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.PERMITTED_PURPOSE','TRUSTED_AI_GOVERNANCE.GOLD.PAYMENT_EXCEPTION_PERIOD_COMPARISON','TABLE'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.DATA_CLASSIFICATION','TRUSTED_AI_GOVERNANCE.GOLD.PAYMENT_EXCEPTION_PERIOD_COMPARISON','TABLE'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.SENSITIVITY_LEVEL','TRUSTED_AI_GOVERNANCE.GOLD.PAYMENT_EXCEPTION_PERIOD_COMPARISON','TABLE')
 UNION ALL SELECT 'SLA_OPERATIONAL_EXPOSURE','OPERATIONS','OPERATIONAL_SENSITIVE','HIGH',SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.DATA_LAYER','TRUSTED_AI_GOVERNANCE.GOLD.SLA_OPERATIONAL_EXPOSURE','TABLE'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.SYNTHETIC_DATA','TRUSTED_AI_GOVERNANCE.GOLD.SLA_OPERATIONAL_EXPOSURE','TABLE'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.DATA_DOMAIN','TRUSTED_AI_GOVERNANCE.GOLD.SLA_OPERATIONAL_EXPOSURE','TABLE'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.OWNER_DOMAIN','TRUSTED_AI_GOVERNANCE.GOLD.SLA_OPERATIONAL_EXPOSURE','TABLE'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.PERMITTED_PURPOSE','TRUSTED_AI_GOVERNANCE.GOLD.SLA_OPERATIONAL_EXPOSURE','TABLE'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.DATA_CLASSIFICATION','TRUSTED_AI_GOVERNANCE.GOLD.SLA_OPERATIONAL_EXPOSURE','TABLE'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.SENSITIVITY_LEVEL','TRUSTED_AI_GOVERNANCE.GOLD.SLA_OPERATIONAL_EXPOSURE','TABLE')
 UNION ALL SELECT 'OPERATIONS_WORKLOAD_SUMMARY','OPERATIONS','GOVERNED_BUSINESS_INFORMATION','MODERATE',SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.DATA_LAYER','TRUSTED_AI_GOVERNANCE.GOLD.OPERATIONS_WORKLOAD_SUMMARY','TABLE'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.SYNTHETIC_DATA','TRUSTED_AI_GOVERNANCE.GOLD.OPERATIONS_WORKLOAD_SUMMARY','TABLE'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.DATA_DOMAIN','TRUSTED_AI_GOVERNANCE.GOLD.OPERATIONS_WORKLOAD_SUMMARY','TABLE'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.OWNER_DOMAIN','TRUSTED_AI_GOVERNANCE.GOLD.OPERATIONS_WORKLOAD_SUMMARY','TABLE'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.PERMITTED_PURPOSE','TRUSTED_AI_GOVERNANCE.GOLD.OPERATIONS_WORKLOAD_SUMMARY','TABLE'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.DATA_CLASSIFICATION','TRUSTED_AI_GOVERNANCE.GOLD.OPERATIONS_WORKLOAD_SUMMARY','TABLE'),SYSTEM$GET_TAG('TRUSTED_AI_GOVERNANCE.GOVERNANCE.SENSITIVITY_LEVEL','TRUSTED_AI_GOVERNANCE.GOLD.OPERATIONS_WORKLOAD_SUMMARY','TABLE')
)
SELECT PRODUCT,'GOLD / TRUE / '||DOMAIN||' / BANKING_OPERATIONS / TRUSTED_BANKING_OPERATIONS_AI / '||CLASSIFICATION||' / '||SENSITIVITY EXPECTED,
 CONCAT_WS(' / ',LAYER,SYNTHETIC,ACTUAL_DOMAIN,OWNER,PURPOSE,ACTUAL_CLASSIFICATION,ACTUAL_SENSITIVITY) ACTUAL,
 IFF(LAYER='GOLD' AND SYNTHETIC='TRUE' AND ACTUAL_DOMAIN=DOMAIN AND OWNER='BANKING_OPERATIONS'
  AND PURPOSE='TRUSTED_BANKING_OPERATIONS_AI' AND ACTUAL_CLASSIFICATION=CLASSIFICATION AND ACTUAL_SENSITIVITY=SENSITIVITY,'PASS','FAIL') RESULT FROM T;

SELECT 'PRODUCT_CATALOG' CHECK_NAME,5 EXPECTED,COUNT(*) ACTUAL,
 IFF(COUNT(*)=5 AND COUNT_IF(AI_CONTEXT_ADMISSION_REQUIRED)=5,'PASS','FAIL') RESULT
FROM GOVERNANCE.GOLD_PRODUCT_CATALOG WHERE EFFECTIVE_STATUS='APPROVED_FOR_EXECUTION';
SELECT 'METRIC_CATALOG' CHECK_NAME,10 EXPECTED,COUNT(*) ACTUAL,IFF(COUNT(*)=10,'PASS','FAIL') RESULT
FROM GOVERNANCE.GOLD_METRIC_CATALOG WHERE EFFECTIVE_STATUS='APPROVED_FOR_EXECUTION';
SELECT 'MINIMIZED_COLUMNS' CHECK_NAME,0 EXPECTED,COUNT(*) ACTUAL,IFF(COUNT(*)=0,'PASS','FAIL') RESULT
FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA='GOLD' AND COLUMN_NAME IN
('CUSTOMER_NAME','EMAIL','PHONE','ADDRESS','POSTAL_CODE','ASSIGNED_ANALYST_ID','ACCOUNT_ID','CUSTOMER_ID');
